function getChapters(lang) {
  if (lang === "hi" || lang === "हिन्दी (Hindi)") return dpdpaChaptersHi;
  if (lang === "mr" || lang === "मराठी (Marathi)") return dpdpaChaptersMr;
  return dpdpaChaptersEn;
}

const dpdpaChapters = dpdpaChaptersEn;
